def transform(grid):
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}

    # Candidate tiles are either a full 2x2 square (color 1) or a 2x2
    # square missing one corner. The missing corner determines the color.
    candidates = []
    for r in range(h - 1):
        for c in range(w - 1):
            square = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            candidates.append((square, 1))
            for missing, color in [
                ((r, c), 2),
                ((r + 1, c), 3),
                ((r, c + 1), 4),
                ((r + 1, c + 1), 5),
            ]:
                candidates.append((square - {missing}, color))

    by_cell = {cell: [] for cell in occupied}
    for shape, color in candidates:
        for cell in shape:
            if cell in by_cell:
                by_cell[cell].append((shape, color))

    def cover(remaining):
        if not remaining:
            return []
        cell = min(
            remaining,
            key=lambda p: sum(shape <= remaining for shape, _ in by_cell[p])
        )
        for shape, color in by_cell[cell]:
            if shape <= remaining:
                result = cover(remaining - shape)
                if result is not None:
                    return [(shape, color)] + result
        return None

    tiling = cover(occupied)
    out = [[0] * w for _ in range(h)]
    if tiling is not None:
        for shape, color in tiling:
            for r, c in shape:
                out[r][c] = color
    return out
